#define I2S_STATE_REG(i)          (REG_I2S_BASE(i) + 0x006C)
/* I2S_TX_IDLE : RO ;bitpos:[0] ;default: 1'b1 ; */
/*description: 1: i2s_tx is idle state. 0: i2s_tx is working.*/
#define I2S_TX_IDLE  (BIT(0))
